insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g3_fa_v1'
from (values
('117.111.b.1.A',2,'An artist paints a picture of her family eating dinner. Her idea came from...','["life experience", "a weather report", "a bus map", "a math test"]'::jsonb,0,'Artists draw ideas from their own lives.','original'),
('117.111.b.1.A',3,'Drawing a dragon that lives in a cloud castle uses your...','["schedule", "imagination", "locker", "allowance"]'::jsonb,1,'Imagination is a source for original art.','original'),
('117.111.b.1.B',3,'How light or dark a color is, from pale yellow to deep brown, is its...','["texture", "motion", "value", "space"]'::jsonb,2,'Value is lightness or darkness.','original'),
('117.111.b.1.B',3,'When one part of an artwork is larger or smaller than another, the artist is thinking about...','["silence", "bedtime", "volume", "proportion"]'::jsonb,3,'Proportion compares sizes.','original'),
('117.111.b.1.B',4,'A design that feels like all of its parts belong together has...','["unity", "delay", "clutter", "noise"]'::jsonb,0,'Unity makes parts work as a whole.','original'),
('117.111.b.1.B',3,'Using both light and dark shapes in the same picture to make it more interesting adds...','["blame", "contrast and variety", "silence", "boredom"]'::jsonb,1,'Contrast and variety use differences.','original'),
('117.111.b.1.C',3,'Line, shape, color, texture, form, space and value are called the...','["steps of a recipe", "rules of recess", "building blocks of art", "parts of a sentence"]'::jsonb,2,'The elements are the building blocks.','original'),
('117.111.b.1.C',4,'Balance, emphasis, pattern and unity help artists organize their work. They are the principles of...','["weather", "grammar", "sports", "design"]'::jsonb,3,'Principles of design organize elements.','original'),
('117.111.b.2.A',3,'A student paints her walk to school to show a real memory. She is integrating ideas from...','["life experiences", "sports scores", "lunch menus", "spelling rules"]'::jsonb,0,'Original art can come from experience.','original'),
('117.111.b.2.B',3,'Planning where to put the sun, hills and river on your paper is making a...','["report", "composition", "schedule", "calendar"]'::jsonb,1,'Compositions arrange elements.','original'),
('117.111.b.2.C',2,'A picture made using pencils or markers on paper is a...','["print", "ceramic", "drawing", "sculpture"]'::jsonb,2,'Drawings use dry media.','original'),
('117.111.b.2.C',3,'A three-dimensional shape pinched and shaped from clay is a...','["photograph", "poster", "painting", "sculpture"]'::jsonb,3,'Sculptures have form.','original'),
('117.111.b.2.C',3,'Creating art with a camera or tablet uses...','["photographic or digital media", "paint only", "clay", "yarn"]'::jsonb,0,'Digital art and photos use technology.','original'),
('117.111.b.2.C',4,'Using paper, cloth and paint together in one artwork is called...','["single medium", "mixed media", "silent art", "performance"]'::jsonb,1,'Mixed media combines materials.','original'),
('117.111.b.3.A',3,'When you see a picture of people planting a garden long ago, you can tell its main idea is about...','["a storm", "a test", "growing food", "a race"]'::jsonb,2,'Look for what is shown.','original'),
('117.111.b.3.B',3,'Looking at art by a man from long ago and a woman today helps you compare and contrast...','["test scores", "menus", "bus routes", "artists and cultures"]'::jsonb,3,'Compare artworks across time and cultures.','original'),
('117.111.b.3.C',3,'An architect designs...','["buildings", "poems", "songs", "sandwiches"]'::jsonb,0,'Architects design buildings.','original'),
('117.111.b.3.C',3,'An animator makes drawings that...','["stay buried", "appear to move", "cook food", "stay silent"]'::jsonb,1,'Animators create motion.','original'),
('117.111.b.3.C',4,'A person who designs clothes for a living is a fashion...','["referee", "farmer", "designer", "lifeguard"]'::jsonb,2,'Fashion designers plan clothing.','original'),
('117.111.b.3.D',3,'Using symmetry in a butterfly drawing connects art to...','["swimming", "recess", "lunch", "math and science"]'::jsonb,3,'Symmetry is a math idea.','original'),
('117.111.b.4.A',3,'Telling whether a painting has strong emphasis on a bright color is to...','["evaluate the artwork", "hide the artwork", "toss the artwork", "delete the artwork"]'::jsonb,0,'Evaluate means judge using art terms.','original'),
('117.111.b.4.B',3,'Writing a short note about why you made an artwork is an artist...','["bill", "statement", "menu", "receipt"]'::jsonb,1,'Artist statements explain art.','original'),
('117.111.b.4.C',3,'Keeping your best drawings in a folder to see how you have grown is for self...','["punishment", "hunger", "assessment", "travel"]'::jsonb,2,'Portfolios help assess growth.','original'),
('117.112.b.1.A',2,'A child''s voice is usually higher than...','["a whistle", "a flute", "a bird", "an adult man''s voice"]'::jsonb,3,'Children''s voices are higher.','original'),
('117.112.b.1.A',3,'Sorting a recording by listening to see if the singers are children or adults is to...','["categorize voices", "bake voices", "count voices", "paint voices"]'::jsonb,0,'Categorizing means sorting by type.','original'),
('117.112.b.1.B',3,'A flute and an oboe are in the...','["percussion family", "woodwind family", "string family", "brass family"]'::jsonb,1,'Woodwinds are blown with reeds or air.','original'),
('117.112.b.1.B',3,'A violin and a cello are in the...','["brass family", "woodwind family", "string family", "percussion family"]'::jsonb,2,'Strings are bowed or plucked.','original'),
('117.112.b.1.B',3,'A tuba and a trombone are in the...','["percussion family", "woodwind family", "string family", "brass family"]'::jsonb,3,'Brass are buzzed into metal horns.','original'),
('117.112.b.1.B',3,'A tambourine and a triangle are in the...','["percussion family", "brass family", "woodwind family", "string family"]'::jsonb,0,'Percussion instruments are struck or shaken.','original'),
('117.112.b.1.C',3,'The special quality that makes a trumpet sound different from a flute even on the same note is...','["tempo", "timbre", "rest", "beat"]'::jsonb,1,'Timbre is tone color.','original'),
('117.112.b.1.C',3,'Mezzo forte means...','["very loud", "medium soft", "medium loud", "very soft"]'::jsonb,2,'Mezzo means medium.','original'),
('117.112.b.1.C',3,'Mezzo piano means...','["very fast", "very loud", "medium loud", "medium soft"]'::jsonb,3,'Mezzo means medium.','original'),
('117.112.b.1.C',3,'Which word describes how fast or slow the beat moves?','["tempo", "tune", "texture", "timbre"]'::jsonb,0,'Tempo is speed.','original'),
('117.112.b.1.D',4,'A song has a first section, a different middle section, and then the first section returns. This form is...','["binary", "ternary or ABA", "random", "rondo"]'::jsonb,1,'ABA has a return.','original'),
('117.112.b.1.D',4,'When a song moves from a first part to a new contrasting part and stops, it has two sections. This is called...','["ternary form", "no form", "binary form", "a fugue"]'::jsonb,2,'Two parts is binary.','original'),
('117.112.b.2.A',3,'Four sixteenth notes together get the same time as one...','["half note", "whole note", "eighth rest", "quarter note"]'::jsonb,3,'Four sixteenths equal one beat.','original'),
('117.112.b.2.A',3,'A whole note in 4/4 meter lasts how many beats?','["four", "two", "one", "three"]'::jsonb,0,'A whole note fills a measure of four beats.','original'),
('117.112.b.2.A',3,'A whole rest in 4/4 means silence for...','["one beat", "a full measure", "no time", "half a beat"]'::jsonb,1,'A whole rest fills the measure.','original'),
('117.112.b.2.B',4,'The extended pentatonic scale uses notes from the staff. Reading melody on a staff means reading...','["only numbers", "only words", "pitches on lines and spaces", "only colors"]'::jsonb,2,'The staff shows pitch.','original'),
('117.112.b.2.C',3,'A symbol that tells players to get softer gradually is a...','["clef", "rest", "crescendo", "decrescendo"]'::jsonb,3,'Decrescendo gets softer.','original'),
('117.112.b.2.C',3,'A symbol that tells players to get louder gradually is a...','["crescendo", "clef", "decrescendo", "rest"]'::jsonb,0,'Crescendo gets louder.','original'),
('117.112.b.3.A',3,'Singing with accurate intonation means singing...','["too late", "in tune", "too loudly", "without breath"]'::jsonb,1,'Intonation is pitch accuracy.','original'),
('117.112.b.3.A',3,'Keeping the long and short sounds exactly on time with your group is playing with accurate...','["clothing", "chairs", "rhythm", "paper"]'::jsonb,2,'Rhythm is timing.','original'),
('117.112.b.3.B',3,'The song Home on the Range is an example of an American...','["science fact", "bus rule", "menu", "folk song"]'::jsonb,3,'Folk songs are shared traditional songs.','original'),
('117.112.b.3.C',3,'Moving your hands and feet together to a beat is an example of...','["integrated movement", "silence", "standing still", "reading"]'::jsonb,0,'Integrated movement coordinates the body.','original'),
('117.112.b.3.C',3,'Walking, skipping and jumping across the room are...','["stationary skills", "locomotor skills", "written skills", "silent skills"]'::jsonb,1,'Locomotor means traveling.','original'),
('117.112.b.3.D',4,'A repeated rhythm played under a melody is a rhythmic...','["essay", "menu", "ostinato", "border"]'::jsonb,2,'Ostinato is a repeated pattern.','original'),
('117.112.b.3.D',4,'A short repeated melody played under a song is a melodic...','["scale", "solo", "silence", "ostinato"]'::jsonb,3,'Ostinato repeats.','original'),
('117.112.b.3.E',3,'When a score says mezzo forte, you perform with a...','["medium loud sound", "very fast tempo", "whisper", "rest"]'::jsonb,0,'Mezzo forte is medium loud.','original'),
('117.112.b.4.A',3,'Making up a new rhythm on the spot is a rhythmic...','["recipe", "improvisation", "spelling", "map"]'::jsonb,1,'Improvisation is made up in the moment.','original'),
('117.112.b.4.B',3,'Writing down your own short tune to share is a melodic...','["recess", "lunch", "composition", "map"]'::jsonb,2,'Composition is written music.','original'),
('117.112.b.4.C',4,'Making up a simple part to play with a song is creating an...','["appetizer", "answer", "argument", "accompaniment"]'::jsonb,3,'An accompaniment supports a melody.','original'),
('117.112.b.5.A',3,'Playing a singing game with your class from a local tradition is performing music from...','["local cultures", "outer space", "nowhere", "only machines"]'::jsonb,0,'Games connect to culture.','original'),
('117.112.b.5.B',3,'A march, a lullaby and a dance tune are examples of different...','["colors of paint", "styles of music", "types of food", "kinds of weather"]'::jsonb,1,'Different genres and styles exist.','original'),
('117.112.b.5.C',3,'Counting beats in a song uses ideas from...','["swimming", "gym only", "math", "lunch only"]'::jsonb,2,'Counting beats is math.','original'),
('117.112.b.6.A',2,'At a concert, a good audience member applauds...','["while talking", "during the music", "while walking", "at the end of a piece"]'::jsonb,3,'Audience etiquette.','original'),
('117.112.b.6.B',3,'Hearing a rhythm and naming it with the correct music word is recognizing a rhythmic...','["element", "door", "chair", "table"]'::jsonb,0,'Using vocabulary names the pattern.','original'),
('117.112.b.6.C',3,'When a song suddenly gets louder in the middle, you have identified a change in...','["pencil", "dynamics", "weather", "name"]'::jsonb,1,'Dynamics are volume changes.','original'),
('117.112.b.6.C',4,'When a song switches from a violin to a trumpet, there is a change in...','["lunch", "sentence", "timbre", "price"]'::jsonb,2,'Timbre is tone color.','original'),
('117.112.b.6.D',2,'Swaying slowly to calm music is responding through...','["a test", "a quiz", "a map", "movement"]'::jsonb,3,'Movement is a response.','original'),
('117.112.b.6.E',3,'Telling a friend that a piece was fast, loud and had a steady beat is describing a performance using music...','["vocabulary", "laundry", "sports", "weather"]'::jsonb,0,'Describing uses music words.','original'),
('117.113.b.1.A',2,'Acting out feeling happy or sad in a make-believe game is reacting to emotional experiences through creative...','["chores", "play", "lunch", "math"]'::jsonb,1,'Creative play expresses feelings.','original'),
('117.113.b.1.B',3,'Using slow and fast movement to make the space for your scene is creating...','["a bill", "a menu", "playing space", "a clock"]'::jsonb,2,'Movement can define space.','original'),
('117.113.b.1.C',3,'Moving like leaves when you hear soft music is responding to sounds with...','["a book", "a pencil", "a bill", "movement"]'::jsonb,3,'Responding through movement.','original'),
('117.113.b.1.D',3,'Standing very still as a statue in a scene is a way to portray...','["a character", "a weather map", "a menu", "a math fact"]'::jsonb,0,'Characters can be shown with body.','original'),
('117.113.b.2.A',2,'Speaking clearly without yelling and moving without bumping others is safe use of...','["food", "movement and voice", "clothing", "paper"]'::jsonb,1,'Safety in drama.','original'),
('117.113.b.2.B',3,'Telling a story by acting without speaking is narrative...','["math", "reading", "pantomime", "cooking"]'::jsonb,2,'Pantomime uses no words.','original'),
('117.113.b.2.C',3,'Using a flashlight to make a character appear on a wall is called shadow...','["test", "art class", "map", "play"]'::jsonb,3,'Shadow play tells stories.','original'),
('117.113.b.2.C',3,'A sock with button eyes that acts out a story is a...','["puppet", "ruler", "trumpet", "calendar"]'::jsonb,0,'Puppets can act out stories.','original'),
('117.113.b.2.D',4,'Acting out a book scene using body motions and copying what characters say is using pantomime and imitative...','["distance", "dialogue", "dessert", "dinner"]'::jsonb,1,'Dialogue is spoken words.','original'),
('117.113.b.3.A',3,'Props, costumes and sound are technical...','["chess pieces", "lunch items", "theatre elements", "math tools"]'::jsonb,2,'They support character and setting.','original'),
('117.113.b.3.B',3,'Wearing a paper crown to show you are a king is using a simple...','["score", "rule", "recipe", "costume"]'::jsonb,3,'Costumes show character.','original'),
('117.113.b.3.B',3,'A cardboard tree on stage is a simple...','["prop or set piece", "recipe", "ticket", "score"]'::jsonb,0,'Props and set pieces show environment.','original'),
('117.113.b.3.C',3,'Deciding who plays each role before a pretend scene is how you...','["cancel it", "plan dramatic play", "forget it", "erase it"]'::jsonb,1,'Planning helps rehearsal.','original'),
('117.113.b.3.D',2,'Sharing ideas and listening in a group scene is...','["argument", "hiding", "cooperation", "bullying"]'::jsonb,2,'Cooperation helps theatre.','original'),
('117.113.b.3.E',3,'Watching a play at a theatre or a video of a show is how you...','["test a theory", "bake a cake", "play a game", "observe a theatrical performance"]'::jsonb,3,'Observing is part of learning theatre.','original'),
('117.113.b.4.A',3,'Acting out a folktale from another culture helps you explore...','["cultural influences", "only math", "nothing", "only recess"]'::jsonb,0,'Stories carry culture.','original'),
('117.113.b.4.B',4,'In a movie the actors may do special effects, but in real life they cannot. This shows a difference between life and...','["bread", "film", "dirt", "rocks"]'::jsonb,1,'Compare life and media.','original'),
('117.113.b.5.A',2,'Audience members should do what during a play?','["run around", "talk and eat loudly", "watch and listen quietly", "use phones loudly"]'::jsonb,2,'Respectful audience behavior.','original'),
('117.113.b.5.B',3,'Saying what worked well in a class skit and what could be better is to...','["fold a performance", "hide a performance", "erase a performance", "evaluate a performance"]'::jsonb,3,'Evaluate means judge fairly.','original'),
('117.113.b.5.C',3,'Talking about how music, movement and costumes made a scene stronger is discussing...','["visual components", "only the weather", "only the seats", "only the tickets"]'::jsonb,0,'Discuss how arts blend.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
